#!/bin/sh
# Provisionamento: execute como root. Nao inicia speedtest.
test '1' = 1 || exit 0; test "$(/usr/bin/id -u)" = 0 || exit 1; PATH=/sbin:/bin:/usr/sbin:/usr/bin:/usr/local/sbin:/usr/local/bin; export PATH; umask 022; mkdir -p /root/scripts || exit 1; p=/root/scripts/pfsense_zbx_update.php; if [ ! -f "$p" ] || [ "$(sha256 -q "$p")" != '53e6aeccb530b3df429d31aaaf42f27d04d6bd3250b918b94a529dd79b95b6f3' ]; then t=$(mktemp /root/scripts/.pfzu-bootstrap.XXXXXX) || exit 1; trap 'test ! -f "$t" || unlink "$t"' 0; curl --fail --silent --show-error --location --proto =https --proto-redir =https --connect-timeout 10 --max-time 45 --max-filesize 1048576 --output "$t" 'https://raw.githubusercontent.com/GBalde409/pfsense_zabbix_scripts/04d1cec36b9d4c0d4b06a2edb056d13ca6a23599/pfsense_zbx_update.php' && [ "$(sha256 -q "$t")" = '53e6aeccb530b3df429d31aaaf42f27d04d6bd3250b918b94a529dd79b95b6f3' ] && /usr/local/bin/php -l "$t" >/dev/null && chmod 0644 "$t" && mv -f "$t" "$p" || exit 1; fi; /usr/local/bin/php "$p" update 'https://raw.githubusercontent.com/GBalde409/pfsense_zabbix_scripts/04d1cec36b9d4c0d4b06a2edb056d13ca6a23599/pfsense_zbx.php' 'eec799ae901baf5cf18326ef910e2ebe49173995b995b650b7234b5853c2256b'
